namespace PipeDream;

/// <summary>
/// Lunar Magic's OVERWORLD ExAnimation hack, transplanted (reference/EXANIMATION.md §10).
/// A separate hack from the level engine (<see cref="LmExAnimEngine"/>), added in LM 2.40 and
/// "based on the same system as the one for levels": its own blob, its own record table, its own
/// global list, its own hooks. Bytes are LM's own, taken from a vanilla ROM it installed the hack
/// into ($10EE94, 0xC20) and moved into bank $1E behind the level engine's blocks.
///
/// The relocation map was proved, not guessed: the same hack installed a second time landed
/// 0x148 bytes further on, and re-pointing this copy by that delta reproduces that one byte for
/// byte. All 266 differing bytes are 12 in-bank 16-bit operands, the 108-word handler table at
/// +B3B, 13 long operands (10 in-blob, and the three that name the two auxiliary tables), and
/// nothing else. The global list's baked immediates (+57 bankword, +61 low16) are zeroed here and
/// patched by the writer, as the level engine's are.
///
/// Three hook sites, all vanilla on a prepped base, all on the overworld's own paths:
/// $048086 (the per-load setup the overworld reaches through `JSR $048086` at $048EEB) → blob+0;
/// $00A4E3 (the overworld's animated-tile VRAM upload) → blob+1F0; $0480E0 (OW_Tile_Animation,
/// the per-frame tick) → blob+500. Each takes `JSL blob : RTS` over five displaced bytes. LM also
/// moves three reads of the frame counter $13 to $14 in what is left of OW_Tile_Animation, and
/// zeroes $03BCC0-CF (already zero once v11 has run).
///
/// The setup reads the submap from `$1F11,X` with `X = $0DB3` (the current player) and indexes
/// the record table by it directly — 3 x submap, no -1, seven entries, FF 00 00 = none. That is
/// the whole difference from the level engine's `[$FE] - 1`.
/// </summary>
internal static class LmOwExAnimEngine
{
    public const int Bank = LmLevelEntry.Bank;
    public const int EngineSnes = (Bank << 16) | 0xA800;             // 0xC20 bytes
    /// <summary>The record pointer table: 3 bytes x 7 submaps, FF 00 00 = that submap has none.
    /// Rom.LmOwExAnimBase finds it through the blob's own operand, as the level table is found.</summary>
    public const int TableSnes = (Bank << 16) | 0xB440;              // 0x15
    /// <summary>One flags byte per submap — Lunar Magic's "Edit Animation Settings" dialog,
    /// OR'd into $7FC00A by the setup. Zero is what LM writes for a fresh install.</summary>
    public const int SettingsSnes = (Bank << 16) | 0xB460;           // 7
    public const int Size = 0xC20, TableSize = 0x15, SettingsSize = 7;
    public const int SetupEntry = EngineSnes, DmaEntry = EngineSnes + 0x1F0, TickEntry = EngineSnes + 0x500;

    /// <summary>Where LM had the blob in the probe ROM — the base every in-bank operand is relative to.</summary>
    private const int SourceSnes = 0x10EE94;

    private static readonly int[] InBankOperands =
        [0x5B7, 0x602, 0x628, 0x62C, 0x63F, 0x6A7, 0x724, 0x7DD, 0x7EB, 0x84A, 0x858, 0x8B5];
    /// <summary>Long operands that point inside the blob (the three naming the tables are separate).</summary>
    private static readonly int[] LongOperands = [0x179, 0x1B9, 0x1C5, 0x619, 0x66A, 0x8F9, 0xA68, 0xA94, 0xAB9, 0xADE];
    private const int HandlerTable = 0xB3B, HandlerTableEnd = 0xC13;  // 108 in-bank words
    public const int TablePlusOneOperand = 0x0D6, TableOperand = 0x0E1, SettingsOperand = 0x04A;
    public const int GlobalBankWord = 0x57, GlobalLow16 = 0x61;

    public static byte[] Engine()
    {
        var b = Convert.FromHexString(Hex);
        int delta = (EngineSnes & 0xFFFF) - (SourceSnes & 0xFFFF);
        void Word(int at) { int v = (b[at] | b[at + 1] << 8) + delta; b[at] = (byte)v; b[at + 1] = (byte)(v >> 8); }
        foreach (int at in InBankOperands) Word(at);
        for (int at = HandlerTable; at < HandlerTableEnd; at += 2) Word(at);
        foreach (int at in LongOperands) { Word(at); b[at + 2] = Bank; }
        Put24(b, TablePlusOneOperand, TableSnes + 1);
        Put24(b, TableOperand, TableSnes);
        Put24(b, SettingsOperand, SettingsSnes);
        return b;
    }

    /// <summary>Seven entries of FF 00 00: no submap has a list until one is written.</summary>
    public static byte[] EmptyTable()
    {
        var t = new byte[TableSize];
        for (int i = 0; i < t.Length; i += 3) t[i] = 0xFF;
        return t;
    }

    public static byte[] EmptySettings() => new byte[SettingsSize];

    public static IEnumerable<(int Snes, byte[] Bytes)> Hooks()
    {
        yield return (0x048086, [0x22, .. Addr(SetupEntry), 0x60]);   // REP #$30 : STZ $03 : STZ …
        yield return (0x00A4E3, [0x22, .. Addr(DmaEntry), 0x60]);     // REP #$10 : LDA #$80 : STA …
        yield return (0x0480E0, [0x22, .. Addr(TickEntry), 0x60]);    // LDA $13 : AND #$07 : BNE …
        // What is left of OW_Tile_Animation reads the OTHER frame counter once LM owns the tick.
        yield return (0x048102, [0x14]);
        yield return (0x04810D, [0x14]);
        yield return (0x04813B, [0x14]);
        yield return (Rom.LmAltExGfxTable, new byte[16]);
    }

    private static byte[] Addr(int snes) => [(byte)snes, (byte)(snes >> 8), (byte)(snes >> 16)];
    private static void Put24(byte[] b, int at, int v) { b[at] = (byte)v; b[at + 1] = (byte)(v >> 8); b[at + 2] = (byte)(v >> 16); }

    private const string Hex = "";
}
